starter_code:
SELECT client_id, jour, LAG(jour) OVER (ORDER BY jour, id) AS precedent
FROM ventes WHERE client_id IS NOT NULL
ORDER BY client_id, jour, id;

solution:
SELECT client_id, jour, LAG(jour) OVER (PARTITION BY client_id ORDER BY jour, id) AS precedent
FROM ventes WHERE client_id IS NOT NULL
ORDER BY client_id, jour, id;

